return [
  {
    json: {
      schema: JSON.stringify({
        customers: {
          columns: {
            customer_id: "integer",
            full_name: "character varying(100)",
            email: "character varying(100)",
            city: "character varying(50)",
            country: "character varying(50)",
            created_at: "timestamp"
          },
          foreign_keys: []
        },
        orders: {
          columns: {
            order_id: "integer",
            customer_id: "integer",
            order_date: "timestamp",
            status: "character varying(20)",
            total_amount: "numeric(10,2)"
          },
          foreign_keys: [
            "customer_id -> customers(customer_id)"
          ]
        },
        payments: {
          columns: {
            payment_id: "integer",
            order_id: "integer",
            payment_date: "timestamp",
            payment_method: "character varying(30)",
            amount: "numeric(10,2)"
          },
          foreign_keys: [
            "order_id -> orders(order_id)"
          ]
        },
        products: {
          columns: {
            product_id: "integer",
            product_name: "character varying(100)",
            category: "character varying(50)",
            unit_price: "numeric(10,2)",
            stock_quantity: "integer"
          },
          foreign_keys: []
        }
      })
    }
  }
];

const inputData = $input.first()?.json || {};

let content =
  inputData.output ??
  inputData.text ??
  inputData.message?.content ??
  "";

let sql = "";

try {
  const parsed =
    typeof content === "string"
      ? JSON.parse(content)
      : content;

  sql = parsed?.sql ?? content;
} catch (e) {
  sql = content;
}

// Clean Markdown wrappers and whitespace
sql = String(sql)
  .replace(/^```(?:sql|json)?\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

// Forbidden SQL keywords
const forbidden = [
  "DROP",
  "DELETE",
  "TRUNCATE",
  "ALTER",
  "INSERT",
  "UPDATE",
  "CREATE",
  "GRANT",
  "REVOKE",
  "EXECUTE",
  "CALL",
  "COPY"
];

const forbiddenPattern = new RegExp(
  "\\b(" + forbidden.join("|") + ")\\b",
  "i"
);

// Require a SELECT statement
const startsWithSelect = /^SELECT\b/i.test(sql);

// Reject multiple statements
const withoutTrailingSemicolon = sql.replace(/;\s*$/, "");
const hasMultipleStatements = withoutTrailingSemicolon.includes(";");

// Reject empty output and obvious natural-language responses
const isSafe =
  sql.length > 0 &&
  startsWithSelect &&
  !forbiddenPattern.test(sql) &&
  !hasMultipleStatements;

// Return validated output
return [
  {
    json: {
      sql,
      is_safe: isSafe,
      reason: isSafe
        ? null
        : "Rejected: output must be a single read-only SELECT statement."
    }
  }
];
